/*
    Styles for implementing WCAG 2.2 AA accessibility on the csc site
 */
header#header .navbar#navbar-main ul.navbar-nav li.nav-item .nav-link:focus-visible {
  outline: 1px solid white;
  outline-offset: 1px;
  margin: 0.5rem;
  padding: 0 0.25rem;
  border-radius: 2px;
}
header#header .navbar#navbar-main ul.navbar-nav li.nav-item ul.dropdown-menu.show {
  display: block;
  min-width: 250px;
  margin: -0.4rem 0 0;
  padding: 0 1rem 0.5rem;
  line-height: 2.5;
  background-color: #fdfdfd;
  color: #232D4B;
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}
header#header .navbar#navbar-main ul.navbar-nav li.nav-item ul.dropdown-menu.show li.dropdown-item {
  padding-top: 0.35rem !important;
  border-bottom: thin solid lightgray;
}
header#header .navbar#navbar-main ul.navbar-nav li.nav-item ul.dropdown-menu.show li.dropdown-item a {
  color: #232D4B !important;
}
header#header .navbar#navbar-main button.navbar-toggler:focus {
  outline: 2px solid red;
}
header#header ul.nav li.nav-item a.nav-link:focus-visible,
header#header a.calendar-link:focus-visible,
header#header div.csc-give-link:focus-visible,
header#header button.search-button:focus-visible {
  outline: 2px solid #fdfdfd;
  outline-offset: 2px;
  border-radius: 2px;
}

/** Reduced Motion **/
@media (prefers-reduced-motion: reduce) {
  [data-aos] {
    opacity: 1 !important;
    -webkit-transform: none !important;
         -o-transform: none !important;
            transform: none !important;
    -webkit-transition: none !important;
    -o-transition: none !important;
    transition: none !important;
  }
}
